/*!
 * Crafted with ❤ by Salla
 */
/**
 * Fast-checkout gate for <salla-mini-checkout-widget> — keeps <salla-add-product-button> thin.
 * Intercepts the widget click at the host's capture phase (an ancestor, so it always runs before
 * the widget's own click handler) → blocks it until Bullet Delivery confirms an address (if it's
 * enabled and nothing is allocated yet) → re-fires the click.
 */
export class FastCheckoutGate {
    constructor() {
        /** True on the re-fired click so it passes through instead of re-gating. */
        this.resuming = false;
        /**
         * Bumped on every gate() call and captured at its start — only the call that still holds the
         * latest token when beforeStartFastCheckout resolves is allowed to resume the widget. This is
         * NOT a lock on starting a new gate() (that promise can stay pending forever by design — e.g.
         * the user closes Bullet Delivery without allocating — and a lock would then permanently kill
         * the button); it only dedupes which of several overlapping resolutions gets to fire the
         * resumed click, so a double-click can't resume the widget twice.
         */
        this.resumeToken = 0;
    }
    /** Attach once to the host. Returns false when there's no widget yet, so the caller retries. */
    static attach(host) {
        const widget = host.querySelector('salla-mini-checkout-widget');
        if (!widget)
            return false;
        const gate = new FastCheckoutGate();
        host.addEventListener('click', (event) => gate.handleClick(event), true);
        return true;
    }
    handleClick(event) {
        if (this.resuming) {
            this.resuming = false;
            return;
        }
        const path = typeof event.composedPath === 'function' ? event.composedPath() : [];
        const widget = path.find((el) => el?.tagName === 'SALLA-MINI-CHECKOUT-WIDGET');
        if (!widget)
            return;
        // Always intercept and defer the "is there anything to gate" decision to Bullet Delivery's
        // own beforeStartFastCheckout listener (hasCompleteIntentForLoggedInUser) — a shortcut check
        // here (e.g. a global scope-id flag) could go stale from an unrelated earlier allocation and
        // silently skip gating this click. This also has to run on every click, not just the first —
        // Bullet Delivery's own reentrancy handling re-prompts (reopens login/the address modal) when
        // a prior attempt is still pending, e.g. after the user dismissed it without allocating.
        event.preventDefault();
        event.stopImmediatePropagation();
        this.gate(widget, ++this.resumeToken);
    }
    async gate(widget, token) {
        await salla.cart.event.beforeStartFastCheckout();
        // A newer click already started its own gate() while this one was waiting (e.g. a
        // double-click) — let that one own the resume, so the widget's real click handler only
        // fires once.
        if (token !== this.resumeToken)
            return;
        this.resuming = true;
        // Real click target lives in the widget's shadow DOM.
        const innerBtn = widget.shadowRoot?.querySelector?.('.s-fast-checkout-button');
        if (innerBtn) {
            innerBtn.click();
        }
        else if (typeof widget.click === 'function') {
            widget.click();
        }
        else {
            this.resuming = false;
        }
    }
}
